  "knowledge": "Treatment Adherence Rate (TAR)",
  "description": "Measures the proportion of patients with high or medium treatment adherence at a facility.",
  "definition": "TAR = \frac{\text{Number of outcomes with Treatment Adherence of 'High', 'Medium', or 'Compliant'}}{\text{Total number of treatment outcomes}} \text{ for a given facility.}"
}

{
  "id": 7,
  "knowledge": "Crisis Intervention Frequency (CIF)",
  "description": "Calculated as the total number of crisis interventions at a facility divided by the total number of unique patients in that facility.",
  "definition": "CIF = \frac{sum \text{Crisis Interventions}}{\text{Total number of unique patients}} \text{ for a given facility.}"
}

{
  "id": 9,
  "knowledge": "Missed Appointment Rate (MAR)",
  "description": "Calculates the average number of missed appointments per patient at a facility.",
  "definition": "MAR = \frac{sum \text{Missed Appointments}}{\text{Total number of unique patients}} \text{ for a given facility.}"
}

{
