  "knowledge": "Stable Recovery Patient",
  "description": "Identifies patients showing stable recovery with good functional outcomes.",
  "definition": "A patient whose recovery status is 'Stable' and whose functional improvement is rated as 'Moderate' or 'Significant'."
}

